import {registerCardComponent} from "@pihanga2/core";

import {TabsComponent} from "./tabs.component";
import {TABS_ACTION, TABS_CARD} from "./tabs.types";

export * from "./tabs.types";

registerCardComponent({
  name: TABS_CARD,
  component: TabsComponent,
  // Explicit mapping avoids CamelCase normalisation issues:
  // TABCHANGED → onTabChanged (lowercase 'c' would break with actionTypesToEvents)
  events: {
    onTabChanged: TABS_ACTION.TABCHANGED,
  },
});

import React, {useState} from "react";
import {Card, type PiCardProps} from "@pihanga2/core";
import {Tabs, TabsContent, TabsList, TabsTrigger} from "@/components/ui/tabs";
import type {TabsEvents, TabsProps} from "./tabs.types";

export const TabsComponent = (
  props: PiCardProps<TabsProps, TabsEvents>,
): React.ReactNode => {
  const {
    tabs,
    value: propValue,
    defaultValue,
    selfManaged = false,
    orientation = "horizontal",
    className,
    listClassName,
    contentClassName,
    cardName,
    onTabChanged,
  } = props;

  // Resolve the initial value for self-managed mode:
  // prefer propValue, then defaultValue, then first tab's id.
  const initialValue = propValue ?? defaultValue ?? tabs[0]?.id ?? "";

  // Internal state used only when selfManaged=true.
  const [managedValue, setManagedValue] = useState<string>(initialValue);

  // Effective active tab:
  //   selfManaged → use internal state
  //   controlled  → use the prop (fall back to first tab if not set)
  const activeValue = selfManaged
    ? managedValue
    : (propValue ?? defaultValue ?? tabs[0]?.id ?? "");

  function handleValueChange(tabId: string) {
    if (selfManaged) {
      setManagedValue(tabId);
    }
    // Always dispatch the Pihanga event so reducers can observe the change
    // even in self-managed mode.
    if (typeof onTabChanged === "function") {
      onTabChanged({tabId});
    }
  }

  return (
    <div data-pihanga={cardName}>
      <Tabs
        value={activeValue}
        onValueChange={handleValueChange}
        orientation={orientation}
        className={className}
      >
        <TabsList className={listClassName}>
          {tabs.map((tab) => (
            <TabsTrigger key={tab.id} value={tab.id} disabled={tab.disabled}>
              {typeof tab.title !== "string" ? (
                <Card cardName={tab.title} parentCard={cardName} />
              ) : (
                tab.title
              )}
            </TabsTrigger>
          ))}
        </TabsList>

        {tabs.map((tab) => (
          <TabsContent key={tab.id} value={tab.id} className={contentClassName}>
            <Card cardName={tab.contentCard} parentCard={cardName} />
          </TabsContent>
        ))}
      </Tabs>
    </div>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  type PiCardRef,
  registerActions,
} from "@pihanga2/core";

export const TABS_CARD = "shad/tabs";

export const SdTabs = createCardDeclaration<TabsProps, TabsEvents>(TABS_CARD);

export const TABS_ACTION = registerActions(TABS_CARD, ["tabChanged"]);

export const onTabsTabChanged = createOnAction<TabsTabChangedEvent>(
  TABS_ACTION.TABCHANGED,
);

// ─── Tab item definition ──────────────────────────────────────────────────────

/**
 * A single tab entry in the tabs component.
 */
export type TabItem = {
  /** Unique identifier used for controlled value and events. */
  id: string;

  /**
   * The label displayed on the tab trigger.
   * Can be a plain string or a PiCardRef for custom/rich tab labels.
   */
  title: string | PiCardRef;

  /**
   * The Pihanga card rendered as the body of this tab when it is active.
   */
  contentCard: PiCardRef;

  /** When true the tab trigger is rendered as disabled. */
  disabled?: boolean;
};

// ─── Card props ───────────────────────────────────────────────────────────────

export type TabsProps = {
  /** Ordered list of tab definitions. */
  tabs: TabItem[];

  /**
   * Controlled: the currently active tab id.
   * Must be provided (or supplied via a state mapper) when selfManaged is
   * false (the default).
   */
  value?: string;

  /**
   * Uncontrolled initial active tab id.
   * Used as the initial value in self-managed mode when value is not set;
   * falls back to the first tab id if omitted.
   */
  defaultValue?: string;

  /**
   * When true, the component manages its own active tab state internally.
   * The onTabChanged event is still dispatched on every change so external
   * reducers can observe the selection.
   *
   * When false (default), value fully controls the displayed tab.
   * @default false
   */
  selfManaged?: boolean;

  /**
   * Layout orientation of the tab list.
   * Passed directly to the Radix Tabs primitive.
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";

  /** Additional Tailwind/CSS classes applied to the root Tabs element. */
  className?: string;

  /** Additional classes applied to the TabsList element. */
  listClassName?: string;

  /** Additional classes applied to each TabsContent element. */
  contentClassName?: string;
};

// ─── Events ───────────────────────────────────────────────────────────────────

export type TabsTabChangedEvent = {
  /** The id of the newly selected tab. */
  tabId: string;
};

export type TabsEvents = {
  /** Fired whenever the user selects a different tab. */
  onTabChanged: TabsTabChangedEvent;
};
